# Construct the 30x30 framed tile grid and add connectors for exceptional center colors 3 and 8.
G=[[0]*30 for _ in range(30)]
row_starts=[1,8,15,22]
col_starts=[1,8,15,22,29]
tile_colors=[[3,2,2,3],[2,8,8,2],[3,2,2,3],[2,8,8,2]]
for ti,r0 in enumerate(row_starts):
    for tj,c0 in enumerate(col_starts):
        for dr in range(5):
            r=r0+dr
            if r>=30: continue
            for dc in range(5):
                c=c0+dc
                if c>=30: continue
                if dr in (0,4) or dc in (0,4):
                    G[r][c]=4
                else:
                    G[r][c]=tile_colors[ti][tj] if tj<4 else 4
# horizontal connections: for each row of tiles and exceptional color, join occurrences.
for ti,r0 in enumerate(row_starts):
    for color in (3,8):
        cols=[tj for tj in range(4) if tile_colors[ti][tj]==color]
        if len(cols)>=2:
            left=col_starts[min(cols)]+1
            right=col_starts[max(cols)]+3
            for r in range(r0+1,r0+4):
                for c in range(left,right+1):
                    if G[r][c]==0: G[r][c]=color
# vertical connections: for each column of tiles and exceptional color, join occurrences.
for tj in range(4):
    for color in (3,8):
        rows=[ti for ti in range(4) if tile_colors[ti][tj]==color]
        if len(rows)>=2:
            top=row_starts[min(rows)]+1
            bottom=row_starts[max(rows)]+3
            for c in range(col_starts[tj]+1,col_starts[tj]+4):
                for r in range(top,bottom+1):
                    if G[r][c]==0: G[r][c]=color
import json
print(json.dumps(G))

